function escapeRegex(s='') { return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function walletKey() { const secret=process.env.SESSION_SECRET||'development-only-change-this-secret-32'; return Buffer.from(crypto.hkdfSync('sha256',Buffer.from(secret),Buffer.from('xwadda-wallet-v1'),Buffer.from('private-data'),32)); }
function encryptPrivate(value) { if(!value)return ''; const iv=crypto.randomBytes(12),cipher=crypto.createCipheriv('aes-256-gcm',walletKey(),iv),encrypted=Buffer.concat([cipher.update(String(value),'utf8'),cipher.final()]); return `v1:${iv.toString('hex')}:${cipher.getAuthTag().toString('hex')}:${encrypted.toString('hex')}`; }
function decryptPrivate(value) { if(!value)return ''; const [version,iv,tag,data]=String(value).split(':'); if(version!=='v1'||!iv||!tag||!data)throw new Error('Saved wallet data could not be decrypted. Check that SESSION_SECRET is unchanged.'); const decipher=crypto.createDecipheriv('aes-256-gcm',walletKey(),Buffer.from(iv,'hex')); decipher.setAuthTag(Buffer.from(tag,'hex')); return Buffer.concat([decipher.update(Buffer.from(data,'hex')),decipher.final()]).toString('utf8'); }
function maskPrivate(value) { const s=String(value||''); return s ? `${'•'.repeat(Math.max(4,s.length-4))}${s.slice(-4)}` : 'Not saved'; }
