function parseCsv(text) {
  const rows=[]; let row=[], field='', quoted=false;
  for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){field+='"';i++;}else if(c==='"')quoted=false;else field+=c;}else if(c==='"')quoted=true;else if(c===','){row.push(field.trim());field='';}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field.trim());field='';if(row.some(value=>value!==''))rows.push(row);row=[];}else field+=c;}
  if(quoted)throw new Error('CSV contains an unclosed quote.');row.push(field.trim());if(row.some(value=>value!==''))rows.push(row);return rows;
}function amountFromForm(value,currency) { if (!/^\d{1,9}(\.\d{1,2})?$/.test(value)) throw new Error('Enter a valid amount.'); if(currency==='KES'&&value.includes('.')) throw new Error('KES amounts must be whole shillings.'); const n=Math.round(Number(value)*100); if(!Number.isSafeInteger(n)||n<1||n>100000000000) throw new Error('Amount is outside the allowed range.'); return n; }
