app.get('/pay/:id',signedIn,async(req,res)=>{
  const [d,account]=await Promise.all([Deal.findOne({publicId:req.params.id,buyerId:req.session.user.id}).lean(),User.findById(req.session.user.id).select('wallet').lean()]);
  if(!d)return res.status(404).send('Deal not found.'); if(d.status!=='awaiting_payment')return res.status(409).send('Deal is not ready for payment.');
  const total=d.amountMinor+d.feeMinor;let payerPhone='';try{payerPhone=decryptPrivate(account?.wallet?.mpesaPhoneEnc)}catch{}
  const html=`<main class="insights-page payment-page"><div class="page-title"><div><span class="eyebrow">PRIVATE CHECKOUT · ROOM ${escapeHtml(d.code||'')}</span><h1>Pay for your deal</h1><p class="subhead">${escapeHtml(d.title)}</p></div><a class="button secondary" href="/deal/${escapeHtml(d.code||d.publicId)}">Back to deal room</a></div><section class="panel-light payment-panel"><div class="payment-total"><span>Agreed amount ${money(d.currency,d.amountMinor)} · fee ${money(d.currency,d.feeMinor)}</span><strong>Total due ${money(d.currency,total)}</strong></div><p class="terms-copy">${escapeHtml(d.terms)}</p>${d.currency==='KES'?`<div class="payment-method-card"><h2>M-Pesa</h2><p>${payerPhone?`Prompt will be sent to your saved number <b>${escapeHtml(maskPrivate(payerPhone))}</b>.`:'Add an M-Pesa number in your wallet to prefill checkout, or enter it in the payment window.'} HashPay opens the M-Pesa payment prompt; approve it on your phone.</p><a class="wallet-inline-link" href="/wallet">Manage wallet and payout details →</a><div class="payment-progress" id="payment-progress" hidden><span class="payment-spinner"></span><div><b id="payment-stage">Preparing payment session…</b><small id="payment-message">Waiting for the M-Pesa prompt and provider confirmation.</small></div></div><p id="paystate" class="payment-state" role="status" aria-live="polite"></p><div class="payment-actions"><button id="mpesa" class="button primary">Continue with M-Pesa</button><button id="resend-prompt" class="button secondary" hidden>Resend M-Pesa prompt</button></div></div><script src="https://pay.hashback.co.ke/hashpay.js"></script><script>(()=>{const csrf=${JSON.stringify(res.locals.csrf)},deal=${JSON.stringify(d.publicId)},payerPhone=${JSON.stringify(payerPhone)},button=document.getElementById('mpesa'),resend=document.getElementById('resend-prompt'),status=document.getElementById('paystate'),progress=document.getElementById('payment-progress'),stage=document.getElementById('payment-stage'),message=document.getElementById('payment-message');let session=null;function wait(t,m){progress.hidden=false;stage.textContent=t;message.textContent=m;progress.classList.add('is-active')}async function poll(){if(!session)return;for(let i=0;i<30;i++){await new Promise(r=>setTimeout(r,3000));try{const r=await fetch('/payment-status.php?id='+encodeURIComponent(session.intent)),j=await r.json();if(j.dealStatus==='funded'){status.textContent='Deposit confirmed in this deal room.';stage.textContent='Deposit confirmed';message.textContent='The verified deposit is reflected for all participants.';progress.classList.remove('is-active');return}if(j.dealStatus==='payment_review'){stage.textContent='Payment received · review in progress';message.textContent='An administrator is checking the transaction reference.';progress.classList.remove('is-active')}}catch{}}status.textContent='Still waiting for a verified update. Do not pay again while status is pending.'}async function openPrompt(){button.disabled=true;resend.disabled=true;status.textContent='';resend.hidden=true;wait('Preparing payment session…','Waiting for the M-Pesa prompt and verified payment update.');try{if(!session){const r=await fetch('/create-mpesa-intent.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({deal})}),j=await r.json();if(!r.ok)throw Error(j.error||'Could not prepare payment.');session=j}const h=HashPay.setup({account:session.account,amount:session.amount,reference:session.reference,phone:payerPhone||undefined,lockPhone:Boolean(payerPhone),onSuccess:async txn=>{wait('Checking payment update…','Waiting for signed confirmation or admin review.');status.textContent='Payment prompt completed. Verifying the transaction…';try{await fetch('/payment/client-result',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({intent:session.intent,receipt:txn?.receipt||'',checkoutid:txn?.checkoutid||''})})}catch{}poll()},onCancel:()=>{progress.classList.remove('is-active');stage.textContent='Prompt closed';message.textContent='Check your phone, then resend if you did not make a payment.';status.textContent='Payment prompt closed. If no payment was made, try again.';resend.hidden=false},onError:()=>{progress.classList.remove('is-active');stage.textContent='Payment response pending';message.textContent='Check the deal status before retrying.';status.textContent='Status uncertain. Do not pay twice; check the room or contact support.';resend.hidden=false}});h.openIframe();poll()}catch(e){status.textContent=e.message;progress.classList.remove('is-active');resend.hidden=false}finally{button.disabled=false;resend.disabled=false}}button.addEventListener('click',openPrompt);resend.addEventListener('click',openPrompt)})();</script>`:`<div class="payment-method-card"><h2>USDT deposit</h2><p>Choose a network, send the exact amount to the configured XWADDA deposit address, then submit the transaction hash. The deal remains pending until verified.</p><a class="wallet-inline-link" href="/wallet">Manage payout addresses →</a><div class="row"><button class="button secondary" data-net="TRC20">USDT · TRC20</button><button class="button secondary" data-net="BEP20">USDT · BEP20</button></div><div id="crypto"></div><p id="crypto-state" class="payment-state" role="status" aria-live="polite"></p></div><script>const csrf=${JSON.stringify(res.locals.csrf)},deal=${JSON.stringify(d.publicId)},total=${JSON.stringify((total/100).toFixed(2))},wallets={TRC20:{address:${JSON.stringify(process.env.TRC20_ADDRESS||'')},qr:'/assets/usdt-trc20-qr.png'},BEP20:{address:${JSON.stringify(process.env.BEP20_ADDRESS||'')},qr:'/assets/usdt-bep20-qr.png'}};document.querySelectorAll('[data-net]').forEach(b=>b.onclick=async()=>{b.disabled=true;const state=document.getElementById('crypto-state');state.textContent='Preparing deposit session…';try{const network=b.dataset.net.toLowerCase()==='trc20'?'tron':'bsc',r=await fetch('/create-crypto-intent.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({deal,network})}),j=await r.json();if(!r.ok)throw Error(j.error||'Could not prepare deposit');const w=wallets[b.dataset.net];document.getElementById('crypto').innerHTML='<p>Send exactly '+total+' USDT on '+b.dataset.net+'</p><img width="220" src="'+w.qr+'" alt="Deposit QR"><p><code>'+w.address+'</code></p><p>Reference: '+j.reference+'</p><form id="tx"><label>Transaction hash<input name="tx_hash" pattern="[a-fA-F0-9]{64}" minlength="64" maxlength="64" required></label><button class="button primary">Submit for verification</button></form>';document.getElementById('tx').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,q=await fetch('/submit-crypto-hash.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({intent:j.intent,tx_hash:form.tx_hash.value})}),x=await q.json();state.textContent=q.ok?'Hash submitted. Waiting for admin verification.':x.error||'Submission failed.'};state.textContent='Deposit session ready. Waiting for your transfer.'}catch(e){state.textContent=e.message}finally{b.disabled=false}})</script>`}<div class="payment-disclaimer">Only confirmed payment events change the deal status. Opening a prompt or submitting a receipt alone does not mean funds arrived.</div></section></main>`;
  res.send(render('Payment',html,req));
});
app.post('/create-mpesa-intent.php',signedIn,checkCsrf,async(req,res)=>{const d=await Deal.findOne({publicId:String(req.body.deal||''),buyerId:req.session.user.id,status:'awaiting_payment'});if(!d||d.currency!=='KES')return res.status(409).json({error:'This deal is not available for M-Pesa payment.'});if(!process.env.HASHPAY_ACCOUNT_ID||!process.env.HASHPAY_WEBHOOK_SECRET)return res.status(503).json({error:'HashBack HashPay merchant credentials are not configured.'});const existing=await PaymentIntent.findOne({dealId:d._id,provider:'hashpay',status:'pending'});if(existing)return res.json({intent:String(existing._id),account:process.env.HASHPAY_ACCOUNT_ID,amount:existing.amountMinor/100,reference:existing.providerReference});const cutoff=new Date(Date.now()-5*60*60*1000),now=new Date(),renewed=await Deal.findOneAndUpdate({_id:d._id,buyerId:req.session.user.id,status:'awaiting_payment',updatedAt:{$gt:cutoff}},{$set:{updatedAt:now}},{new:true});if(!renewed)return res.status(409).json({error:'This room has been inactive for five hours and is closing. Create a new room to continue.'});const reference='XW'+d.publicId.toUpperCase()+crypto.randomBytes(4).toString('hex').toUpperCase(),intent=await PaymentIntent.create({dealId:d._id,provider:'hashpay',providerReference:reference,amountMinor:d.amountMinor+d.feeMinor,currency:'KES'});res.json({intent:String(intent._id),account:process.env.HASHPAY_ACCOUNT_ID,amount:intent.amountMinor/100,reference});});
app.post('/payment/client-result',signedIn,checkCsrf,async(req,res)=>{const p=await PaymentIntent.findOne({_id:String(req.body.intent||''),provider:'hashpay',status:'pending'}).populate('dealId');if(!p||!p.dealId||String(p.dealId.buyerId)!==req.session.user.id)return res.status(404).json({error:'Payment attempt not found.'});const receipt=String(req.body.receipt||'').trim().slice(0,40),checkoutid=String(req.body.checkoutid||'').trim().slice(0,120);p.providerPayload={...(p.providerPayload||{}),clientReportedSuccess:true,clientReportedReceipt:receipt,clientReportedAt:new Date(),checkoutid};await p.save();const d=await Deal.findOneAndUpdate({_id:p.dealId._id,status:{$in:['awaiting_payment','payment_review']}},{$set:{status:'payment_review',paymentRef:p.providerReference,paymentMethod:'mpesa',updatedAt:new Date()}},{new:true});if(d&&d.status==='payment_review')await addRoomEvent(d,req.session.user,'buyer','M-Pesa checkout returned a receipt. Deposit remains under verification until a signed provider event or admin review.');res.json({ok:true,verified:false});});
app.get('/payment-status.php',signedIn,async(req,res)=>{const p=await PaymentIntent.findById(String(req.query.id||'')).populate('dealId');if(!p||!p.dealId||String(p.dealId.buyerId)!==req.session.user.id)return res.status(404).json({error:'Payment not found.'});res.json({status:p.status,dealStatus:p.dealId.status});});
app.post('/create-crypto-intent.php',signedIn,checkCsrf,async(req,res)=>{const d=await Deal.findOne({publicId:String(req.body.deal||''),buyerId:req.session.user.id,status:'awaiting_payment'});const network=String(req.body.network||'');if(!d||d.currency!=='USDT'||!['tron','bsc'].includes(network))return res.status(409).json({error:'This USDT deal is not available for that network.'});let intent=await PaymentIntent.findOne({dealId:d._id,provider:'crypto',status:'pending'});if(intent&&intent.network!==network)return res.status(409).json({error:'A payment attempt exists on another network. Contact support before switching.'});if(!intent){const cutoff=new Date(Date.now()-5*60*60*1000),now=new Date();const renewed=await Deal.findOneAndUpdate({_id:d._id,buyerId:req.session.user.id,status:'awaiting_payment',updatedAt:{$gt:cutoff}},{$set:{updatedAt:now}},{new:true});if(!renewed)return res.status(409).json({error:'This room has been inactive for five hours and is closing. Create a new room to continue.'});intent=await PaymentIntent.create({dealId:d._id,provider:'crypto',providerReference:'XWCR'+d.publicId.toUpperCase()+crypto.randomBytes(3).toString('hex').toUpperCase(),network,amountMinor:d.amountMinor+d.feeMinor,currency:'USDT'});}res.json({intent:String(intent._id),reference:intent.providerReference});});
app.post('/submit-crypto-hash.php',signedIn,checkCsrf,async(req,res)=>{const hash=String(req.body.tx_hash||'').toLowerCase().trim();if(!/^[a-f0-9]{64}$/.test(hash))return res.status(422).json({error:'Enter a valid 64-character transaction hash.'});const intent=await PaymentIntent.findOne({_id:String(req.body.intent||''),provider:'crypto',status:'pending'}).populate('dealId');if(!intent||!intent.dealId||String(intent.dealId.buyerId)!==req.session.user.id||intent.dealId.status!=='awaiting_payment')return res.status(409).json({error:'This payment is no longer awaiting a transaction hash.'});const reviewDeal=await Deal.findOneAndUpdate({_id:intent.dealId._id,status:'awaiting_payment'},{$set:{txHash:hash,cryptoNetwork:intent.network==='tron'?'TRC20':'BEP20',status:'payment_review',updatedAt:new Date()}},{new:true});intent.providerPayload={customer_tx_hash:hash,submitted_at:new Date()};if(!reviewDeal){intent.status='exception';await intent.save();return res.status(409).json({error:'Room is no longer awaiting payment. Contact support immediately with your transaction hash.'});}await intent.save();res.json({ok:true});});
app.post('/hashpay-webhook.php',async(req,res)=>{const secret=process.env.HASHPAY_WEBHOOK_SECRET,account=process.env.HASHPAY_ACCOUNT_ID;if(!secret||!account)return res.status(503).send('Webhook is not configured.');const signature=String(req.get('x-hashpay-signature')||''),expected='sha256='+crypto.createHmac('sha256',secret).update(req.rawBody||'').digest('hex'),sig=Buffer.from(signature),exp=Buffer.from(expected);if(!signature||sig.length!==exp.length||!crypto.timingSafeEqual(sig,exp))return res.status(401).send('Invalid signature.');const payload=req.body||{};if(String(payload.AccountID||'')!==account)return res.status(403).send('Unexpected account.');const reference=String(payload.TransactionReference||''),txId=String(payload.TransactionID||''),event=String(payload.event||''),code=String(payload.ResponseCode||'');if(!reference||!txId||!['payment.success','payment.failed'].includes(event))return res.status(400).send('Missing payment fields.');const p=await PaymentIntent.findOne({provider:'hashpay',providerReference:reference});if(!p)return res.status(404).send('Unknown payment reference.');if(p.status!=='pending')return res.status(200).send('Already processed.');const received=Number.isFinite(Number(payload.TransactionAmount))?Math.round(Number(payload.TransactionAmount)*100):-1;const d=await Deal.findById(p.dealId);let ok=event==='payment.success'&&code==='0'&&received===p.amountMinor&&d&&['awaiting_payment','payment_review'].includes(d.status);if(ok){const funded=await Deal.findOneAndUpdate({_id:d._id,status:{$in:['awaiting_payment','payment_review']}},{$set:{status:'funded',depositedAt:new Date(),mpesaReceipt:String(payload.TransactionReceipt||txId),paymentRef:reference,paymentMethod:'mpesa',updatedAt:new Date()}},{new:true});ok=Boolean(funded);if(funded)await addRoomEvent(funded,null,'system','M-Pesa deposit confirmed by signed HashPay webhook.');}if(event==='payment.failed'&&d?.status==='payment_review')await Deal.updateOne({_id:d._id,status:'payment_review'},{$set:{status:'awaiting_payment',updatedAt:new Date()}});p.status=ok?'confirmed':(event==='payment.success'?'exception':'failed');p.providerTransactionId=txId;p.providerReceipt=String(payload.TransactionReceipt||txId);p.providerPayload={event,ResponseCode:code,TransactionID:txId,TransactionReceipt:payload.TransactionReceipt,TransactionAmount:payload.TransactionAmount,TransactionDate:payload.TransactionDate,TransactionReference:reference};await p.save();res.status(200).send('OK');});
// HashPay callback verification is deliberately unavailable until HashBack's exact signing format is configured.
app.post('/webhooks/hashpay',async(req,res)=>{if(!process.env.HASHPAY_WEBHOOK_SECRET)return res.status(503).send('Payment webhook is not configured.');const signature=String(req.get('x-hashback-signature')||'');const raw=JSON.stringify(req.body);const expected=crypto.createHmac('sha256',process.env.HASHPAY_WEBHOOK_SECRET).update(raw).digest('hex');if(!signature||!crypto.timingSafeEqual(Buffer.from(signature),Buffer.from(expected)))return res.status(401).send('Invalid signature.');return res.status(501).send('Configure the exact HashBack signed payload and settlement fields before accepting payment callbacks.');});

app.use('/assets',express.static(path.join(__dirname,'public','assets'),{immutable:true,maxAge:'7d'}));
app.use((req,res,next)=>{if(req.path.endsWith('.php')||req.path==='/app-loader.php')return res.status(404).send('This PHP route is retired. Use the Node.js route.');next();});
app.use((err,req,res,next)=>{console.error(err);res.status(500).send('A server error occurred. Please try again later.');});

async function connectMongoWithRetry(){
  while(mongoose.connection.readyState!==1){
    try {
      await mongoose.connect(mongoUri,{dbName:mongoDbName,serverSelectionTimeoutMS:10000,connectTimeoutMS:10000});
      console.log(`MongoDB connected to database ${mongoDbName}.`);
      if(process.env.ADMIN_EMAIL) await User.updateOne({email:process.env.ADMIN_EMAIL.toLowerCase()},{role:'admin'},{runValidators:true});
    } catch(e) {
      console.error('MongoDB is not ready. Check that MONGODB_URI uses the live MongoDB resource internal hostname (not localhost or 127.0.0.1), and that both Coolify resources share a network.');
      console.error(e && e.message ? e.message : e);
      await new Promise(resolve=>setTimeout(resolve,5000));
    }
  }
}
const AUTO_CLOSE_STATUSES=['open','awaiting_seller','draft','accepted','awaiting_payment'];
async function closeInactiveUnfundedDeals(){
  if(mongoose.connection.readyState!==1)return;
  const cutoff=new Date(Date.now()-5*60*60*1000), now=new Date();
  const candidates=await Deal.find({status:{$in:AUTO_CLOSE_STATUSES},updatedAt:{$lte:cutoff}}).select('_id code').limit(100).lean();
  for(const candidate of candidates){
    const closed=await Deal.findOneAndUpdate({_id:candidate._id,status:{$in:AUTO_CLOSE_STATUSES},updatedAt:{$lte:cutoff}},{$set:{status:'cancelled',closedAt:now,closeReason:'inactive_unfunded_timeout',updatedAt:now}},{new:true});
    if(closed){await PaymentIntent.updateMany({dealId:closed._id,status:'pending'},{$set:{status:'failed'}});await addRoomEvent(closed,null,'system','Automatically cancelled after five hours without activity. No deposit was confirmed.');}
  }
}
const server=app.listen(port,'0.0.0.0',()=>{
  console.log(`XWADDA listening on 0.0.0.0:${port}; checking MongoDB database ${mongoDbName}.`);
  connectMongoWithRetry().catch(e=>console.error('MongoDB reconnect loop stopped:',e));
});
server.on('error',error=>{console.error('HTTP server failed to listen:',error.message);process.exit(1);});
setInterval(()=>closeInactiveUnfundedDeals().catch(error=>console.error('Automatic unfunded-room cleanup failed:',error.message)),60*1000).unref();
